skyRadianceGLSL:
float skyAtmosphereScatter(float y){
 float horizonPath=exp(-abs(y)*15.0);
 float upperScatter=exp(-max(y,0.)*8.0);
 float lowerScatter=exp(-max(-y,0.)*23.0);
 float scatter=horizonPath*.24+upperScatter*lowerScatter*.08;
 return clamp(scatter,0.,.32);
}
float skyAtmosphereChannel(float sampleChannel,float luminance,float air,float scatter){
 float col=mix(luminance,sampleChannel,1.-scatter*.12);
 return mix(col,air,scatter);
}
vec3 skyEnvironmentRadiance(vec3 direction,vec3 sampleColor){
 vec3 d=normalize(direction);
 // Linear RGB, approximately sRGB #76b5ce: keep colour in the horizon haze.
 vec3 horizonAir=vec3(.1812,.4621,.6172);
 float scatter=skyAtmosphereScatter(d.y);
 float luminance=dot(sampleColor,vec3(.2126,.7152,.0722));
 return vec3(skyAtmosphereChannel(sampleColor.r,luminance,horizonAir.r,scatter),
             skyAtmosphereChannel(sampleColor.g,luminance,horizonAir.g,scatter),
             skyAtmosphereChannel(sampleColor.b,luminance,horizonAir.b,scatter));
}
